#include <stdio.h>

#define INF 1000000000

int adj[105][105];
int dist[105];
int used[105];

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    for (int i = 1; i <= N; i++)
        for (int j = 1; j <= N; j++)
            adj[i][j] = INF;

    for (int i = 0; i < M; i++) {
        int a, b, c;
        scanf("%d %d %d", &a, &b, &c);
        if (c < adj[a][b]) {
            adj[a][b] = c;
            adj[b][a] = c;
        }
    }

    for (int i = 1; i <= N; i++) dist[i] = INF;
    dist[1] = 0;

    for (int i = 1; i <= N; i++) {
        int u = -1;
        for (int j = 1; j <= N; j++)
            if (!used[j] && (u == -1 || dist[j] < dist[u]))
                u = j;
        if (u == -1 || dist[u] == INF) break;
        used[u] = 1;
        if (u == N) break;
        for (int v = 1; v <= N; v++)
            if (!used[v] && adj[u][v] != INF && dist[u] + adj[u][v] < dist[v])
                dist[v] = dist[u] + adj[u][v];
    }

    printf("%d\n", dist[N]);
    return 0;
}
